<template>
  <div>
    <template v-if="type === 'picture'">
      <a-flex wrap="wrap">
        <div v-for="(item, index) in fileList" :key="index">
          <a-image
            v-if="imgFileType.includes(getType(item.fileUrl))"
            :src="item.fileUrl"
            :preview="{
              visible: false,
              onVisibleChange: () => {
                openPreviewModal(index);
              },
            }"
            :style="{ padding: '2px', height: '100px' }"
            :width="width"
            fallback="data:image/png;base64,"
          />
          <video
            v-else
            :style="{ width: width + 'px', height: height + 'px', cursor: 'pointer' }"
            @click="
              () => {
                openPreviewModal(index);
              }
            "
          >
            <source :src="item.url" />
          </video>
        </div>
      </a-flex>
    </template>
    <a-button v-if="type === 'text'" :disabled="fileList.length === 0" size="small" type="link" @click="openPreviewModal"> View </a-button>
    <FilePreviewModal ref="previewModalRef" :fileList="oFileList" title="Image Preview" />
  </div>
</template>
<script setup>
  import { computed, ref } from 'vue';
  import FilePreviewModal from '../file-preview-modal/index.vue';
  import { imgFileType } from '/@/constants/common-const';

  let props = defineProps({
    fileList: {
      type: Array,
      default: () => {
        return [];
      },
    },
    // type: text, picture
    type: {
      type: String,
      default: 'text',
    },
    // image width
    width: {
      type: Number,
      default: 100,
    },
    height: {
      type: Number,
      default: 100,
    },
    // separator, can be set to an HTML tag, e.g. <br/>
    separator: {
      type: String,
      default: ', ',
    },
  });
  const getType = (url = '') => {
    return url.match(/[^/]+\.(\w{2,})$/) && '.' + url.match(/[^/]+\.(\w{2,})$/)[1];
  };
  const oFileList = computed(() => {
    return props.fileList.map((item) => ({ url: item.fileUrl }));
  });

  const previewModalRef = ref(null);
  const openPreviewModal = (index = 0) => {
    previewModalRef.value.open(index);
  };
</script>
